/** Generated by scripts/prepare-lesson-audio.cjs --bind after reviewed en-GB files exist. */
export interface PreparedLessonAudio { text: string; locale: 'en-GB'; asset: number }
export const preparedLessonAudio: PreparedLessonAudio[] = [];
export function preparedAudioSource(text: string): number | undefined {
  const key = (value: string) => value.replace(/[‘’]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase();
  return preparedLessonAudio.find(item => item.locale === 'en-GB' && key(item.text) === key(text))?.asset;
}
